// The shared hidden-character vectors (M6 spec §4.7, D138), slice 6c.
// `tests/fixtures/export/hidden-vectors.json` is generated by
// `scripts/fixtures/make_synthetic_exports.py` and read by this test and by
// the export's classifier in Rust, so "Copy text without invisible
// characters" (D121) and the export's markers stay the inverse of each
// other: the copy keeps exactly the pieces classed `keep` and `cr`.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { withoutHiddenCharacters } from '@/services/copyText';

interface Piece {
  text: string;
  class: 'keep' | 'bidi' | 'invisible' | 'joiner' | 'tag' | 'vsRun' | 'control' | 'cr';
}

interface Vector {
  name: string;
  pieces: Piece[];
  text: string;
  withoutHiddenCharacters: string;
  markedCodePoints: string[];
}

// Relative to the app directory, where Vitest runs (as safe-text.spec.ts).
const FILE = 'tests/fixtures/export/hidden-vectors.json';
const doc = JSON.parse(readFileSync(FILE, 'utf8')) as { format: string; vectors: Vector[] };

describe('hidden-character vectors', () => {
  it('is the vector file', () => {
    expect(doc.format).toBe('oma-hidden-vectors');
    expect(doc.vectors.length).toBeGreaterThanOrEqual(30);
  });

  it.each(doc.vectors.map((v) => [v.name, v] as const))('%s', (_name, v) => {
    expect(v.pieces.map((p) => p.text).join('')).toBe(v.text);
    const kept = v.pieces
      .filter((p) => p.class === 'keep' || p.class === 'cr')
      .map((p) => p.text)
      .join('');
    expect(kept).toBe(v.withoutHiddenCharacters);
    expect(withoutHiddenCharacters(v.text)).toBe(v.withoutHiddenCharacters);
  });
});
